) -> [Result<u64>; 4] {
    let inputs: [Result<(u64, u64, u64)>; 4] = std::array::from_fn(|lane| {
        let level = upper - lane;
        let node = self.nodes.get(prediction.indexes[level])
            .ok_or("CTS update node outside bounds")?;
        if node.weight > Q {
            return Err("CTS update weight outside bounds".into());
        }
        let pk = if bit {
            Q.checked_sub(prediction.kt[level]).ok_or("CTS KT complement underflow")?
        } else { prediction.kt[level] };
        let child = if bit {
            Q.checked_sub(prediction.zero[level + 1]).ok_or("CTS child complement underflow")?
        } else { prediction.zero[level + 1] };
