            node.weight, prediction.weights[level], pk, child, prediction.zero[level],
            (prediction.remainder >> level) & 1 != 0, bit,
        )?;
        probability(pk)?;
        if ceiling == 0 { return Err("CTS zero denominator".into()); }
        Ok((node.weight, pk, ceiling))
    });
    // 無効laneを0/1へ置換し、正常laneの浮動小数除算へ影響させない。
    let a = std::array::from_fn(|lane| inputs[lane].as_ref().map_or(0, |v| v.0));
    let b = std::array::from_fn(|lane| inputs[lane].as_ref().map_or(1, |v| v.1));
    let d = std::array::from_fn(|lane| inputs[lane].as_ref().map_or(1, |v| v.2));
    let quotients = table.ratio4(a, b, d);
    std::array::from_fn(|lane| match &inputs[lane] {
        Err(error) => Err(error.clone()),
        Ok(_) => {
            let (posterior, _) = quotients[lane]
                .map_err(|_| "CTS ratio product overflow".to_string())?;
            if posterior > Q { return Err("CTS posterior outside bounds".into()); }
            Ok(posterior)
        }
    })
}
